use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let cents = arr[0].as_i64().unwrap();
    let n = arr[1].as_u64().unwrap() as i64;

    let mut shares = vec![0; n as usize];
    let mut remaining = cents;

    for i in 0..n {
        let share = remaining / n + if i < remaining % n { 1 } else { 0 };
        shares[i as usize] = share;
        remaining -= share;
    }

    Value::Array(shares.into_iter().map(Value::from).collect())
}
